package com.greenocean.backend;
import org.flywaydb.core.Flyway;import org.junit.jupiter.api.Test;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.jdbc.datasource.DriverManagerDataSource;import java.util.*;import static org.assertj.core.api.Assertions.*;
class PhaseMMigrationTest extends MigrationTestSupport {
 @Test void populatedLRetainsGroupsAndConservativelyRestrictsDiscussion(){String url=System.getenv("GREENOCEAN_TEST_DB_URL"),schema="qa_m_"+UUID.randomUUID().toString().replace("-","");var source=new DriverManagerDataSource(url,System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD",""));
  Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).target("46").load().migrate();var db=new JdbcTemplate(new DriverManagerDataSource(url+(url.contains("?")?"&":"?")+"currentSchema="+schema+",public",System.getenv().getOrDefault("GREENOCEAN_TEST_DB_USER","postgres"),System.getenv().getOrDefault("GREENOCEAN_TEST_DB_PASSWORD","")));
  try{UUID owner=db.queryForObject("INSERT INTO users(email,password_hash,status) VALUES('m-legacy@example.test','preserved-hash','ACTIVE') RETURNING id",UUID.class);db.update("INSERT INTO profiles(user_id,username,display_name) VALUES(?,'m_legacy','Historical')",owner);
   for(boolean privacy:List.of(false,true)){UUID group=db.queryForObject("INSERT INTO communities(name,slug,is_private,created_by) VALUES(?,?,?,?) RETURNING id",UUID.class,"Historical "+privacy,"historical-"+privacy,privacy,owner);db.update("INSERT INTO community_members(community_id,user_id,role) VALUES(?,?,'OWNER')",group,owner);db.update("INSERT INTO posts(author_id,community_id,body,is_anonymous,visibility) VALUES(?,?,'Historical story',TRUE,'COMMUNITY')",owner,group);}
   var groups=db.queryForList("SELECT id,is_private,created_by,status FROM communities ORDER BY id");var posts=db.queryForList("SELECT id,is_anonymous,visibility,community_id FROM posts ORDER BY id");var f=Flyway.configure().dataSource(source).schemas(schema).defaultSchema(schema).load();f.migrate();f.validate();
   assertThat(db.queryForList("SELECT id,is_private,created_by,status FROM communities ORDER BY id")).isEqualTo(groups);assertThat(db.queryForList("SELECT id,is_anonymous,visibility,community_id FROM posts ORDER BY id")).isEqualTo(posts);assertThat(db.queryForObject("SELECT count(*) FROM communities WHERE privacy_type=CASE WHEN is_private THEN 'PRIVATE' ELSE 'PUBLIC' END",Integer.class)).isEqualTo(2);assertThat(db.queryForObject("SELECT count(*) FROM community_proposals",Integer.class)).isZero();
  }finally{db.execute("DROP SCHEMA "+schema+" CASCADE");}
 }
}
